files.content:
* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: 'Courier New', ui-monospace, monospace;
  background: #0f172a; color: #e2e8f0; min-height: 100vh;
}
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 18px; background: #1e293b; border-bottom: 1px solid #334155;
}
.brand { font-weight: 800; color: #38bdf8; }
.badge { font-size: 11px; border: 1px solid #38bdf8; color: #38bdf8; border-radius: 99px; padding: 2px 10px; }
.console { display: grid; grid-template-columns: 250px 1fr; min-height: calc(100vh - 54px); }
.endpoints { background: #1e293b; border-right: 1px solid #334155; padding: 14px; }
.endpoints h2 { font-size: 11px; text-transform: uppercase; color: #94a3b8; margin-bottom: 10px; letter-spacing: .05em; }
.ep {
  display: block; width: 100%; text-align: left; background: transparent; border: 0;
  color: #cbd5e1; padding: 8px 10px; border-radius: 8px; cursor: pointer;
  font-family: inherit; font-size: 12px; margin-bottom: 4px;
}
.ep:hover { background: #334155; }
.ep.active { background: #38bdf8; color: #0f172a; font-weight: 700; }
.play { padding: 18px; }
.req { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; flex-wrap: wrap; }
.method { background: #38bdf8; color: #0f172a; font-weight: 900; padding: 4px 10px; border-radius: 6px; font-size: 12px; }
.path { color: #e2e8f0; font-size: 14px; }
.id-input {
  background: #1e293b; border: 1px solid #334155; color: #fff;
  border-radius: 6px; padding: 6px 8px; width: 64px; font-family: inherit;
}
.btn { background: #22c55e; color: #0f172a; border: 0; padding: 8px 16px; border-radius: 8px; font-weight: 800; cursor: pointer; font-family: inherit; }
label { display: block; font-size: 11px; color: #94a3b8; text-transform: uppercase; margin-bottom: 6px; letter-spacing: .05em; }
textarea {
  width: 100%; background: #1e293b; color: #e2e8f0; border: 1px solid #334155;
  border-radius: 8px; padding: 10px; font-family: inherit; font-size: 12px; margin-bottom: 16px;
}
.res h3 { font-size: 12px; color: #94a3b8; margin-bottom: 8px; font-weight: 600; }
.status { border-radius: 6px; padding: 2px 8px; font-size: 11px; margin-left: 8px; }
.status.ok { background: #22c55e; color: #0f172a; }
.status.err { background: #ef4444; color: #fff; }
pre {
  background: #1e293b; border: 1px solid #334155; border-radius: 8px;
  padding: 14px; font-size: 12px; min-height: 120px; overflow: auto;
}

const data = [
  { id: 1, name: 'Budi Santoso', email: 'budi@mail.com' },
  { id: 2, name: 'Siti Rahma', email: 'siti@mail.com' },
  { id: 3, name: 'Andi Wijaya', email: 'andi@mail.com' }
]
let nextId = 4

const methodEl = document.getElementById('method')
const pathEl = document.getElementById('path')
const idInput = document.getElementById('idInput')
const bodyEl = document.getElementById('body')
const bodyLabel = document.querySelector('label[for="body"]')
const outputEl = document.getElementById('output')
const statusEl = document.getElementById('status')
const eps = document.querySelectorAll('.ep')

let current = { method: 'GET', path: '/api/users' }

eps.forEach((el) => el.addEventListener('click', () => {
  eps.forEach((x) => x.classList.remove('active'))
  el.classList.add('active')
  current = { method: el.dataset.method, path: el.dataset.path }
  methodEl.textContent = current.method
  pathEl.textContent = current.path
  const needsBody = current.method === 'POST' || current.method === 'PUT'
  bodyLabel.style.display = needsBody ? 'block' : 'none'
  bodyEl.style.display = needsBody ? 'block' : 'none'
}))

function respond(code, obj) {
  statusEl.textContent = code
  statusEl.className = 'status ' + (String(code).startsWith('2') ? 'ok' : 'err')
  outputEl.textContent = JSON.stringify(obj, null, 2)
}

document.getElementById('sendBtn').addEventListener('click', () => {
  const { method, path } = current
  const id = Number(idInput.value) || 1

  if (method === 'GET' && !path.includes(':id')) {
    return respond('200', { data, total: data.length })
  }
  if (method === 'GET' && path.includes(':id')) {
    const u = data.find((x) => x.id === id)
    return u ? respond('200', u) : respond('404', { error: 'User tidak ditemukan' })
  }

  let parsed
  if (method === 'POST' || method === 'PUT') {
    try { parsed = JSON.parse(bodyEl.value) } catch { return respond('400', { error: 'JSON tidak valid' }) }
  }

  if (method === 'POST') {
    const user = { id: nextId++, ...parsed }
    data.push(user)
    return respond('201', { message: 'User dibuat', user })
  }
  if (method === 'PUT') {
    const idx = data.findIndex((x) => x.id === id)
    if (idx === -1) return respond('404', { error: 'User tidak ditemukan' })
    data[idx] = { ...data[idx], ...parsed, id }
    return respond('200', { message: 'User diperbarui', user: data[idx] })
  }
  if (method === 'DELETE') {
    const idx = data.findIndex((x) => x.id === id)
    if (idx === -1) return respond('404', { error: 'User tidak ditemukan' })
    const [removed] = data.splice(idx, 1)
    return respond('200', { message: 'User dihapus', user: removed })
  }
})
